"""National Weather Service — MCP server generated by Handyman.

Tools for retrieving US weather forecasts, observations, alerts, and text products from the National Weather Service (weather.gov). Most location-based tools accept latitude/longitude and internally resolve NWS grid/office identifiers, so agents never need to know about grids, WFOs, or zones directly. Use get_forecast for a human-readable forecast, get_current_observations for the latest reported conditions near a point, get_active_alerts for hazards, and get_text_product for official bulletins.

Source API: https://api.weather.gov/openapi.json
Regenerate with: handyman generate https://api.weather.gov/openapi.json
"""

import os
from typing import Annotated, Any

import httpx
from arcade_mcp_server import MCPApp

app = MCPApp(
    name='nws',
    version="0.1.0",
    log_level="ERROR",
    instructions='Tools for retrieving US weather forecasts, observations, alerts, and text products from the National Weather Service (weather.gov). Most location-based tools accept latitude/longitude and internally resolve NWS grid/office identifiers, so agents never need to know about grids, WFOs, or zones directly. Use get_forecast for a human-readable forecast, get_current_observations for the latest reported conditions near a point, get_active_alerts for hazards, and get_text_product for official bulletins.',
)

BASE_URL = 'https://api.weather.gov'

# ---------------------------------------------------------------------------
# Request plumbing — the single HTTP door every tool goes through
# ---------------------------------------------------------------------------


def _request(
    method: str,
    path: str,
    params: dict[str, Any] | None = None,
    headers: dict[str, str] | None = None,
) -> Any:
    """Issue one API request and return parsed JSON, raising a readable error
    on HTTP failure so the calling agent can react."""
    all_headers = dict(_DEFAULT_HEADERS)
    all_headers.update(headers or {})
    response = httpx.request(
        method,
        BASE_URL + path,
        params=params or None,
        headers=all_headers,
        timeout=30,
        follow_redirects=True,
    )
    if response.status_code >= 400:
        raise RuntimeError(f"{method} {path} failed ({response.status_code}): {response.text[:300]}")
    return response.json()


def _dig(payload: Any, path: str) -> Any:
    """Follow a dot path into a JSON payload, failing loudly when it is absent.
    Used between chained calls, where a missing value means the chain is wrong."""
    value = payload
    for key in path.split("."):
        if not isinstance(value, dict) or key not in value:
            available = sorted(value.keys()) if isinstance(value, dict) else type(value).__name__
            raise RuntimeError(f"response missing '{path}' (at '{key}'; found: {available})")
        value = value[key]
    return value


def _prune(payload: Any, path: str) -> Any:
    """Best-effort final shaping: return the payload at a dot path, or the full
    payload when the shape drifted — a bigger answer beats a broken tool."""
    value = payload
    for key in path.split("."):
        if not isinstance(value, dict) or key not in value:
            return payload
        value = value[key]
    return value


def _as_object(value: Any) -> dict:
    """Tools always return a JSON object; non-object payloads are wrapped."""
    return value if isinstance(value, dict) else {"result": value}


# Identification values with safe defaults; override via environment. A
# secret with no default is omitted entirely until its variable is set —
# httpx rejects None header values.
_DEFAULT_HEADERS = {
    key: value
    for key, value in {
        'User-Agent': os.environ.get('NWS_USER_AGENT', 'weather-mcp-server (contact@example.com)'),
        'API-Key': os.environ.get('NWS_API_KEY', None),
    }.items()
    if value is not None
}


# ---------------------------------------------------------------------------
# Tools
# ---------------------------------------------------------------------------


@app.tool
def get_forecast(
    latitude: Annotated[float, 'Latitude of the location in decimal degrees.'],
    longitude: Annotated[float, 'Longitude of the location in decimal degrees.'],
    units: Annotated[str, "Unit system for the textual output: 'us' (customary, default) or 'si' (metric)."] = "us",
) -> Annotated[dict, 'List of forecast periods (name, temperature, wind, short/detailed forecast text) for the given point.']:
    """
    Gets the multi-day textual weather forecast (e.g. 'Tonight', 'Monday', 'Monday
    Night') for a US latitude/longitude point. Use this for general 'what's the weather
    going to be like' questions covering the next 7 days. Not for hour-by-hour detail
    (use get_hourly_forecast) and not for current conditions (use
    get_current_observations). Returns a list of forecast periods with temperature,
    wind, and short/detailed narrative descriptions.
    """
    response_1 = _request("GET", f"/points/{latitude},{longitude}")
    wfo = _dig(response_1, 'properties.gridId')
    grid_x = _dig(response_1, 'properties.gridX')
    grid_y = _dig(response_1, 'properties.gridY')
    params_2: dict[str, Any] = {}
    params_2['units'] = units
    response_2 = _request("GET", f"/gridpoints/{wfo}/{grid_x},{grid_y}/forecast", params=params_2)
    return _as_object(_prune(response_2, 'properties.periods'))


@app.tool
def get_hourly_forecast(
    latitude: Annotated[float, 'Latitude of the location in decimal degrees.'],
    longitude: Annotated[float, 'Longitude of the location in decimal degrees.'],
    units: Annotated[str, "Unit system for the textual output: 'us' (customary, default) or 'si' (metric)."] = "us",
) -> Annotated[dict, 'List of hourly forecast periods (start/end time, temperature, wind, short forecast text) for the given point.']:
    """
    Gets the hour-by-hour weather forecast for a US latitude/longitude point, typically
    covering the next 1-2 days. Use this when an agent needs fine-grained timing (e.g.
    'will it rain at 3pm today') rather than the daily-period forecast from
    get_forecast. Returns a list of hourly periods with start/end times, temperature,
    and short forecast text.
    """
    response_1 = _request("GET", f"/points/{latitude},{longitude}")
    wfo = _dig(response_1, 'properties.gridId')
    grid_x = _dig(response_1, 'properties.gridX')
    grid_y = _dig(response_1, 'properties.gridY')
    params_2: dict[str, Any] = {}
    params_2['units'] = units
    response_2 = _request("GET", f"/gridpoints/{wfo}/{grid_x},{grid_y}/forecast/hourly", params=params_2)
    return _as_object(_prune(response_2, 'properties.periods'))


@app.tool
def get_current_observations(
    latitude: Annotated[float, 'Latitude of the location in decimal degrees.'],
    longitude: Annotated[float, 'Longitude of the location in decimal degrees.'],
) -> Annotated[dict, 'Latest observation for the nearest station: timestamp, temperature, wind, humidity, pressure, and textual description.']:
    """
    Gets the most recent weather observation (temperature, wind, humidity, pressure,
    textual description) from the observation station nearest a US latitude/longitude
    point. Use this for 'what's the weather right now' questions. Not for forecasts.
    """
    response_1 = _request("GET", f"/points/{latitude},{longitude}/stations")
    station_id = _dig(response_1, 'observationStations.0')
    response_2 = _request("GET", f"/stations/{station_id}/observations/latest")
    return _as_object(_prune(response_2, 'properties'))


@app.tool
def get_active_alerts(
    area: Annotated[str | None, "Two-letter US state/territory code or marine area code (e.g. 'CA', 'TX', 'GM'). Comma-separated for multiple."] = None,
    point: Annotated[str | None, "Latitude,longitude pair (e.g. '39.7456,-97.0892') to find alerts covering that location."] = None,
) -> Annotated[dict, 'List of active alert features, each with properties like event, severity, headline, description, and affected area.']:
    """
    Gets currently active weather alerts (watches, warnings, advisories) for a US
    state/territory code, marine area, or a specific latitude/longitude point. Use this
    to check for hazardous weather conditions. Provide either area or a point, not both.
    Returns a list of active alerts with event type, severity, headline, and
    description.
    """
    params: dict[str, Any] = {}
    if area is not None:
        params['area'] = area
    if point is not None:
        params['point'] = point
    response = _request("GET", '/alerts/active', params=params)
    return _as_object(_prune(response, 'features'))


@app.tool
def get_alert_details(
    alert_id: Annotated[str, 'The unique identifier of the alert.'],
) -> Annotated[dict, 'Full alert record including area description, affected zones, timing, status, and message type.']:
    """
    Gets full details for a single weather alert by its unique alert ID (as returned in
    get_active_alerts results). Use this when an agent already has an alert ID and needs
    the complete record, including affected zones and references. Not for searching
    alerts.
    """
    response = _request("GET", f"/alerts/{alert_id}")
    return _as_object(_prune(response, 'properties'))


@app.tool
def get_text_product(
    product_id: Annotated[str, 'The unique identifier of the text product.'],
) -> Annotated[dict, 'Text product record with issuing office, issuance time, product code/name, and full product text.']:
    """
    Gets the full text of a specific NWS text product bulletin (e.g. area forecast
    discussion, special weather statement) by its product ID. Use this when an agent
    already has a product ID, such as from get_latest_text_product. Returns the raw
    issuing office, timing metadata, and full product text.
    """
    response = _request("GET", f"/products/{product_id}")
    return _as_object(response)


@app.tool
def get_latest_text_product(
    product_type: Annotated[str, "Product type code, e.g. 'AFD' (Area Forecast Discussion), 'SPS' (Special Weather Statement), 'ZFP' (Zone Forecast Product)."],
    location_id: Annotated[str, "NWS issuance location code, typically the 3-letter forecast office or station identifier (e.g. 'OKX')."],
) -> Annotated[dict, 'The latest text product for the given type and location, including full product text.']:
    """
    Gets the most recently issued text product of a given type (e.g. 'AFD' for Area
    Forecast Discussion, 'SPS' for Special Weather Statement) for a given NWS issuance
    location (typically a 3-letter office/station code). Use this to get the current
    forecast discussion or statement for an office without knowing specific product IDs.
    Returns the full product text.
    """
    response = _request("GET", f"/products/types/{product_type}/locations/{location_id}/latest")
    return _as_object(response)


if __name__ == "__main__":
    import sys

    app.run(transport=sys.argv[1] if len(sys.argv) > 1 else "stdio")
